            Anchors += '    <span class="media-body block m-b-none">Charges Request for Quot : <span>' + item.QuotationRouteRequestCode + '</span><br><small class="text-muted"> - Sender :' + item.SenderName + ' (' + item.SendingDateAndTime + ')</small></span>';
