function removeLeadingHyphen(str) {
    debugger;
    if (str.startsWith('-')) {
        return str.slice(1); // Remove the first character
    }
    if (str.startsWith(' -')) {
        return str.slice(2); // Remove the first character
    }
    return str; // Return the original string if it doesn't start with '-'
}

