function DocsOut_Print_MAN_BL1(OperationID, DocType) {
    debugger;
    if (DocType == 221)
        var pWhereClause = " WHERE ID = " + 220;
    else
        var pWhereClause = " WHERE ID = " + DocType;
    var pParametersWithValues = {
        pWhereClause: pWhereClause,
        pDocumentTypeID: DocType,
        pOperationID: OperationID,
        pReportTypeID: 3, // $("#ulDocsOutReportTypes .active").val() // 3: pdf, 4: rtf
        pTruckingOrderID: 0,
        pSelectedPayableIDs: "0",
        pSelectedReceivableIDs: "0",
        pWithVAT: false,
        pCommodityID: 0
    };

    CallGETFunctionWithParameters("/api/Reports/Report_DocsOut", pParametersWithValues, function (data) {
        if (DocType == 220 || DocType == 125 || DocType == 130 || DocType == 135 || DocType == 221) {
            $.ajaxSetup({ cache: true });

            $.getScript(strServerURL + '/Scripts/Operations/Operations/docsout.js' + '?version=' + version, function () {
                switch (DocType) {
                    case 220:
                        if (data[2] == "0") { // means house
                            DocsOut_Print_MAN_BL(OperationID);
                        } else {
                            DocsOut_Print_MAN_MBL(OperationID);
                        }
                        break;
                    case 125:
                        DocsOut_Print_DeliveryOrder(data, 125, "Print");
                        break;
                    case 130:
                    case 135:
                        DocsOut_Print_LetterRelease(data, DocType, "Print");
                        break;
                    case 221:
                        if (data[2] == "0") { // means house
                            DocsOut_Print_HBL_LATILS_AIR("AIRHBL", OperationID);
                        } else {
                            DocsOut_Print_HBL_LATILS_AIR("AIR", OperationID);
                        }
                        break;
                    default:
                        console.log("Unknown DocType: " + DocType);
                }
            });

            $.ajaxSetup({ cache: false });
        }
    });
}





