                    $("#txtTblModalReceivableSalePrice" + item.ID).val(item.CostPrice);
                    $("#txtTblModalReceivableSaleAmount" + item.ID).val(item.CostPrice * (item.Quantity == 0 ? 1 : item.Quantity));
