function SetIndexForTable(pTableID, pClassName) {
    $('#' + pTableID + ' > tbody  > tr').each(function (currentIndex, currentRow) {
        $(currentRow).find('.' + pClassName).html((currentIndex * 1) + 1);
    });
}

