function ExportHtmlTableToCsv_RemovingCommasForNumbers_New(pTblName, pFileName) {
    debugger;
    function exportToCsv() {
        var CsvString = "";
        var mytable = document.getElementById(pTblName);
        if (!mytable) return;

        var thead = mytable.querySelector("thead");
        var tbody = mytable.querySelector("tbody");
        if (!thead || !tbody) return;

        var headers = thead.getElementsByTagName("th");
        var colCount = headers.length;

        // Header
        for (var j = 0; j < colCount; j++) {
            CsvString += headers[j].innerText + ",";
        }
        CsvString += "\r\n";

        // Rows
        var rows = tbody.getElementsByTagName("tr");
        for (var i = 0; i < rows.length; i++) {
            var cells = rows[i].getElementsByTagName("td");
            for (var j = 0; j < colCount; j++) {
                var cellText = cells[j] ? cells[j].innerText.replace(/,/g, "") : "";

                // Preserve leading zeros if the value looks like a number (e.g., "012345")
                if (/^0\d+$/.test(cellText)) {
                    cellText = '="' + cellText + '"';
                }

                CsvString += cellText + ",";
            }
            CsvString += "\r\n";
        }

        CsvString = "data:text/csv;charset=utf-8,%EF%BB%BF" + encodeURIComponent(CsvString);
        var a = document.createElement("a");
        a.setAttribute("href", CsvString);
        if (!pFileName) pFileName = "NewFile";
        if (typeof getTodaysDateInddMMyyyyFormat === "function" && typeof getTime === "function") {
            a.setAttribute("download", pFileName + ' ' + getTodaysDateInddMMyyyyFormat() + ' ' + getTime() + ".csv");
        } else {
            a.setAttribute("download", pFileName + ".csv");
        }
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }
    exportToCsv();
}

