function FilterGridBasedOnFilterInput(GridID, FilterInputID) {
    debugger;
    let Filter = $("#" + FilterInputID).val().toUpperCase();
    if (Filter == "") {
        $("#" + GridID).children("div").removeClass("hide");
    } else {
        $("#" + GridID).children().each(function () {
            debugger;
            var id = $(this).attr("id"); // get the id of the child div
            var label = $(this).find("label"); // get the label element inside the child div
            var text = label.text().toUpperCase(); // get the text in the label
            if (text.includes(Filter)) { // check if the text contains the Filter word
                $(this).removeClass("hide"); // remove the hide class to the parent div
            } else {
                $(this).addClass("hide"); // add the hide class to the parent div
            }
        })
    }


}

function IsEnglish(txt) {
    txt = IsNull(txt, "").replace(/[.*+?^${}()|[\]\\]/g, "").replace(/ /g, "");
    var english = /^[A-Za-z0-9]*$/;
    var isEnglish = english.test(txt);
    return isEnglish;
}

