function Select2OnlineSearch(pSelectID, pCalledControllerAPI, pDataFn, pProcessResultsFn, pMinimumInputLength, pDelayInMilli, pAllowClear = false, pPlaceholder = null) {
    // pDataFn function gets params as a parameter by default from select2 which contains params.term(search term)
    // and must return object with query parameters
    // pProcessResultsFn gets data as a parameter and must return object with results property
    // results property must be array of item objects
    // each item object must have id,text,value properties
    $("#" + pSelectID).select2({
        ajax: {
            url: strServerURL + pCalledControllerAPI,
            dataType: 'json',
            type: "GET",
            contentType: "application/json; charset=utf-8",
            delay: pDelayInMilli,
            data: pDataFn,
            processResults: pProcessResultsFn
        },
        minimumInputLength: pMinimumInputLength,
        width: "100%",
        allowClear: pAllowClear,
        placeholder: pAllowClear ? pPlaceholder : null
    });
}

