(function () {
    var oldSelect2 = jQuery.fn.select2;
    jQuery.fn.select2 = function () {
        const modalParent = jQuery(this).closest('.modal-content');
        if (arguments.length === 0 && modalParent.length > 0) {
            arguments = [{ dropdownParent: modalParent }];
        } else if (arguments.length === 1
            && typeof arguments[0] === 'object'
            && typeof arguments[0].dropdownParent === 'undefined'
            && modalParent.length > 0) {
            arguments[0].dropdownParent = modalParent;
        }
        return oldSelect2.apply(this, arguments);
    };
    for (var key in oldSelect2) {
        jQuery.fn.select2[key] = oldSelect2[key];
    }
})();




function UnfInvoicePrint(ID) {
    debugger;
    var InvoiceID = ID;
    var arr_Keys = new Array();
    var arr_Values = new Array();
    arr_Keys.push("id");
    arr_Values.push(InvoiceID);
    arr_Keys.push("printuser");
    arr_Values.push($('#hLoggedUserNameNotLogin').val());
    var ReportName = "";
    if (pDefaults.UnEditableCompanyName == "LIN") {
        ReportName = "Rep_LIN_Invoice";
        var cbCombineTrucking = 'no';
        if ($("#cbCombineTrucking").prop("checked")){
            cbCombineTrucking = 'yes';
        }else{
            cbCombineTrucking = 'no';
        }
        var cbShowOperationNotify = 'no';
        if ($("#CBMVolume").prop("checked")) {
            cbShowOperationNotify = 'yes';
        } else {
            cbShowOperationNotify = 'no';
        }
 
        var Printheader = $("#cbPrintHeaderInvoice").prop("checked");
        var PrintFooter = $("#cbPrintFooterInvoice").prop("checked");
        var PrintNote = $("#cbAddNotesToItems").prop("checked");
        arr_Keys.push("Printheader");
        arr_Values.push(Printheader);
        arr_Keys.push("PrintFooter");
        arr_Values.push(PrintFooter);
        arr_Keys.push("PrintNote");
        arr_Values.push(PrintNote);
        arr_Keys.push("cbCombineTrucking");
        arr_Values.push(cbCombineTrucking);
        arr_Keys.push("cbShowOperationNotify");
        arr_Values.push(cbShowOperationNotify);
    }
    if (pDefaults.UnEditableCompanyName == "REL") {
        ReportName = "Rep_REL_Invoice"
    }
    if (pDefaults.UnEditableCompanyName == "UNF" && (pDefaults.CompanyName.includes("UNIFREIGHT") || window.location.href.includes("unifreight"))) {
        ReportName = "Rep_UNF_Invoice"
        if (glbCallingControl == "WH_CFS_Invoices"){
            ReportName = "Rep_UNF_LCL_Invoice"

        }else{
            ReportName = "Rep_UNF_Invoice"

        }
        var Printhead = $("#cbPrintHeaderInvoice").prop("checked");
        var PrintFoot = $("#cbPrintFooterInvoice").prop("checked");
        var PrintNotes = $("#cbAddNotesToItems").prop("checked");
        var ArabicItems = $("#cbPrintArabicItems").prop("checked");
        var VolumeCBM = $("#CBMVolume").prop("checked");
        arr_Keys.push("Printhead");
        arr_Values.push(Printhead);
        arr_Keys.push("PrintFoot");
        arr_Values.push(PrintFoot);
        arr_Keys.push("PrintNotes");
        arr_Values.push(PrintNotes);
        arr_Keys.push("ArabicItems");
        arr_Values.push(ArabicItems);
        arr_Keys.push("VolumeCBM");
        arr_Values.push(VolumeCBM);

        arr_Keys.push("UserName");
        arr_Values.push($('#hLoggedUserNameNotLogin').val());

    }
    if (pDefaults.UnEditableCompanyName == "UNF" && (pDefaults.CompanyName.includes("CPWorld") || window.location.href.includes("cpworld"))) {
        if (glbCallingControl == "WH_CFS_Invoices") {
            ReportName = "Rep_CPW_Invoice_lcl"

        } else {
            ReportName = "Rep_CPW_Invoice"

        }
        var Printhead = $("#cbPrintHeaderInvoice").prop("checked");
        var PrintFoot = $("#cbPrintFooterInvoice").prop("checked");
        var PrintNotes = $("#cbAddNotesToItems").prop("checked");
        var ArabicItems = $("#cbPrintArabicItems").prop("checked");
        var VolumeCBM = $("#CBMVolume").prop("checked");
        arr_Keys.push("Printhead");
        arr_Values.push(Printhead);
        arr_Keys.push("PrintFoot");
        arr_Values.push(PrintFoot);
        arr_Keys.push("PrintNotes");
        arr_Values.push(PrintNotes);
        arr_Keys.push("ArabicItems");
        arr_Values.push(ArabicItems);
        arr_Keys.push("VolumeCBM");
        arr_Values.push(VolumeCBM);

        arr_Keys.push("UserName");
        arr_Values.push($('#hLoggedUserNameNotLogin').val());

    }
    var pParametersWithValues =
    {
        arr_Keys: arr_Keys
        , arr_Values: arr_Values
        , pTitle: "Invoice"
        , pReportName: ReportName
    };
    var win = window.open("", "_blank");
    var url = '/ReportMainClass/PrintReport?pTitle="' + pParametersWithValues.pTitle + '"' + '&arr_Keys=' + pParametersWithValues.arr_Keys + '' + '&arr_Values=' + pParametersWithValues.arr_Values + '&pReportName=' + pParametersWithValues.pReportName + '';

    win.location = url;

}
