function removeLeadingDash(str) {
    if (str.startsWith('-')) {
        return str.substring(1);
    }
    return str;
}

function UNFReleaseLetterPrint(ReportType) {
    debugger;

    var OPHID = $("#slDocsOutOperations").val();
    var OPID = $("#hOperationID").val();
    var arr_Keys = new Array();
    var arr_Values = new Array();
    arr_Keys.push("HID");
    arr_Values.push(OPHID);
    arr_Keys.push("ID");
    arr_Values.push(OPID);
    var ReportName = "";
    var title = "";
    if (ReportType == "LetterRelease"){
        title = "ReleaseLetter";
        if (pDefaults.CompanyLocalName =="UNIFREIGHT GLOBAL LOGISTICS")
        ReportName = "Rep_UNF_ReleaseLetter";
        else 
            ReportName = "Rep_CPW_ReleaseLetter";

    } else if (ReportType == "DeliveryOrder") {
        title = "DeliveryOrder";
        var UserName = $('#hLoggedUserNameNotLogin').val();
        arr_Keys.push("USER");
        arr_Values.push(UserName);
        if (pDefaults.CompanyLocalName == "UNIFREIGHT GLOBAL LOGISTICS")
            ReportName = "Rep_UNF_DeliveryOrder";
        else
            ReportName = "Rep_CPW_DeliveryOrder";

    }

    var pParametersWithValues =
    {
        arr_Keys: arr_Keys
        , arr_Values: arr_Values
        , pTitle: title
        , pReportName: ReportName
    };
    var win = window.open("", "_blank");
    var url = '/ReportMainClass/PrintReport?pTitle="' + pParametersWithValues.pTitle + '"' + '&arr_Keys=' + pParametersWithValues.arr_Keys + '' + '&arr_Values=' + pParametersWithValues.arr_Values + '&pReportName=' + pParametersWithValues.pReportName + '';

    win.location = url;

}
function NTMReports(ReportTypeID) {
    debugger;


    if (ReportTypeID == 220 && $("#hTransportType").val() == 2) {
        DocsOut_Print(220, 0, OPHID);
    }
    else {



        var OPHID = $("#slDocsOutOperations").val();
        var OPID = $("#hOperationID").val();
        var arr_Keys = new Array();
        var arr_Values = new Array();
        arr_Keys.push("HID");
        arr_Values.push(OPHID);
        arr_Keys.push("ID");
        arr_Values.push(OPID);
        var ReportName = "";
        var title = "";
        if (($("#cbShowHBLTemplate").prop("checked")) && ReportTypeID == 220 && $("#hTransportType").val() != 2) {
            title = "HBL";
            ReportName = "Rep_NTM_HBL";
            NTMReportsAtt()

        }
        else if (ReportTypeID == 125) {
            title = "DeliveryOrder";
            var UserName = $('#hLoggedUserNameNotLogin').val();
            arr_Keys.push("USER");
            arr_Values.push(UserName);
            ReportName = "Delivery_Order_NTM_Air";


        } else if (ReportTypeID == 530) {
            title = "إيصال نولون جمركي";
            ReportName = "Nawlon_NTM";


        }
        else if (ReportTypeID == 540) {
            title = "عقد إتفاق";
            ReportName = "Contract_NTM";


        }
        else if (ReportTypeID == 140) {
            title = "BookingConfirmation";
            ReportName = "Booking-NTM";


        }
        else if (ReportTypeID == 550) {
            title = "HOUSE CARGO MANIFEST";
            ReportName = "HOUSECARGOMANIFEST_AIR_NTM";


        }
        else if (ReportTypeID == 120 && pDefaults.UnEditableCompanyName == "NTMU") {
            title = "Delivery Order";
            ReportName = "Delivery_Order_NTM_US";


        }
        else if (ReportTypeID == 560 && pDefaults.UnEditableCompanyName == "NTMU") {
            title = "Work Order";
            ReportName = "WorkOrder_NTM";


        }
        else if ((!$("#cbShowHBLTemplate").prop("checked")) && ReportTypeID == 220 && $("#hTransportType").val() != 2) {
            title = "HBL";
            ReportName = "Rep_NTM_HBLEmpty";
            NTMReportsAtt()
        }

        var pParametersWithValues =
        {
            arr_Keys: arr_Keys
            , arr_Values: arr_Values
            , pTitle: title
            , pReportName: ReportName
        };
        var win = window.open("", "_blank");
        var url = '/ReportMainClass/PrintReport?pTitle="' + pParametersWithValues.pTitle + '"' + '&arr_Keys=' + pParametersWithValues.arr_Keys + '' + '&arr_Values=' + pParametersWithValues.arr_Values + '&pReportName=' + pParametersWithValues.pReportName + '';

        win.location = url;


    }
}


